function validFillVariantKey(q,level,key){let entry=fillEntry(q,level);return entry?.variants?.length?typeof key==='string'&&entry.variants.some(v=>v.key===key):key===''||key==null}
function fallbackFillVariantKey(q,level,paperId=''){let order=variantOrder(q,level);return order.length?order[hashSeed(`fill-legacy-v1:${paperId}:${q.id}`)%order.length]:''}
function nextFillVariantKey(q,level){let order=variantOrder(q,level);return order.length?order[Math.floor(num(S.learning[q.id]?.fillExposure,0,999999))%order.length]:''}
function assignFillVariantKeys(items){for(const item of items){if(item.renderType!=='fill'){item.fillVariantKey='';continue}if(!validFillVariantKey(item.q,item.fillLevel,item.fillVariantKey))item.fillVariantKey=nextFillVariantKey(item.q,item.fillLevel);else item.fillVariantKey=item.fillVariantKey||''}return items}
function resolveFillEntry(q,level='standard',variantKey=''){let entry=fillEntry(q,level);if(!entry?.variants?.length)return entry;let variant=entry.variants.find(v=>v.key===variantKey);return variant?{...entry,...variant}:null}
function isFillEligible(q,level='standard'){let entry=fillEntry(q,level);return !!(entry?.stem||entry?.variants?.length)}
function questionAnswers(q,renderType=q.type,level='standard',variantKey=''){let entry=renderType==='fill'?resolveFillEntry(q,level,variantKey):null;if(renderType==='fill'&&fillEntry(q,level)?.variants?.length&&!entry)return [];return (entry?.answers||q.answers||[]).map(displayText)}
function auditFillBanks(){
  let errors=[],standardIds=Object.keys(FILL_BANK),enhancedIds=Object.keys(ENHANCED_FILL_BANK),full={...FILL_BANK,...ENHANCED_FILL_BANK},dynamicIds=Object.keys(ENHANCED_FILL_BANK).filter(id=>ENHANCED_FILL_BANK[id].variants),variantCount=0;
  if(standardIds.length!==104)errors.push(`标准填空应为104题，实际为${standardIds.length}`);
  if(enhancedIds.length!==104)errors.push(`增强独立填空应为104题，实际为${enhancedIds.length}`);
  if(Object.keys(full).length!==208)errors.push(`增强填空应为208题，实际为${Object.keys(full).length}`);
  for(const [id,e] of Object.entries(full)){
    let q=Q.find(x=>x.id===Number(id));if(!q){errors.push(`#${id}填空原题不存在`);continue}
    if(e.originType&&e.originType!==q.type)errors.push(`#${id}原题类型不匹配`);
    if(e.variants){
      if(!Array.isArray(e.variants)||!e.variants.length)errors.push(`#${id}轮换版本缺失`);
      let keys=new Set;for(const v of e.variants||[]){variantCount++;if(!v.key||keys.has(v.key))errors.push(`#${id}轮换key重复或为空`);keys.add(v.key);if((v.stem?.match(/______/g)||[]).length!==1)errors.push(`#${id}/${v.key}空位数量异常`);if(!Array.isArray(v.answers)||v.answers.length!==1||!v.answers[0]||/以上都是|以上都对/.test(v.answers[0]))errors.push(`#${id}/${v.key}答案异常`);if(!Array.isArray(v.accepted)||!v.accepted.length)errors.push(`#${id}/${v.key}容错答案缺失`)}
    }else{let answers=e.answers||q.answers;if(!e.stem||!e.stem.includes('______'))errors.push(`#${id}填空题干异常`);if(!Array.isArray(answers)||!answers.length)errors.push(`#${id}填空答案缺失`);if(q.type==='judge'&&answers?.some(x=>x==='对'||x==='错'))errors.push(`#${id}判断改填空仍使用对错答案`)}
  }
  if(dynamicIds.length!==18||variantCount!==60)errors.push(`轮换填空应为18题60版本，实际${dynamicIds.length}题${variantCount}版本`);
  for(const id of [176,378,397,418,431,450,473])if(ENHANCED_FILL_BANK[id])errors.push(`#${id}不应在增强填空池`);
  for(const id of [27,28,97,103,105,107,247,254,258,259,260,261,266,268,272,290,308])if(!ENHANCED_FILL_BANK[id])errors.push(`#${id}应在增强填空池`);
  if(ENHANCED_FILL_BANK[168]?.answers?.join()!=='60N·m'||ENHANCED_FILL_BANK[462]?.answers?.join()!=='5Why'||ENHANCED_FILL_BANK[474]?.answers?.join()!=='环境')errors.push('上一轮填空质量修订被覆盖');
  return errors
}
const FILL_AUDIT_ERRORS=auditFillBanks();BANK_AUDIT_ERRORS.push(...FILL_AUDIT_ERRORS);
function rotationState(){S.examRotation=S.examRotation||{round:0,recent:[],usage:{},lastSeenRound:{}};S.examRotation.lastSeenRound=S.examRotation.lastSeenRound||{};return S.examRotation}
function duplicateKey(id){return DUPLICATE_GROUP_BY_ID[id]||`Q${id}`}
function rotationRanks(){let r=rotationState(),rounds=r.recent||[];return {r,recent10:rounds.slice(-10)}}
function learningPriority(q){let l=S.learning[q.id]||{},w=S.wrong[q.id]||{},now=Date.now(),attempts=l.attempts||0,accuracy=attempts?(l.correct||0)/attempts:0,avg=l.timedAttempts?l.totalMs/l.timedAttempts:0;return (w.wrongTotal||w.count||0)*18+(w.wrongStreak||0)*35+(l.assistedCorrect||0)*14+(l.lowConfidenceCorrect||0)*12+(avg>=30000?18:0)+(l.due&&l.due<=now?25:0)+(1-accuracy)*10}
function rankedCandidates(pool,balanced=false){let {r,recent10}=rotationRanks(),round=r.round||0;return pool.map(q=>{let used=num(r.usage[q.id],0),last=num(r.lastSeenRound[q.id],0),gap=last?round-last:999,recencyPenalty=last?Math.max(0,11-gap)*30:0,exposurePenalty=used*100,learn=balanced?learningPriority(q):0,random=Math.random();return {q,score:exposurePenalty+recencyPenalty-learn,random}}).sort((a,b)=>a.score-b.score||a.random-b.random)}
function coveragePick(pool,n,blocked=new Set(),balanced=false){let blockedGroups=new Set([...blocked].map(duplicateKey)),out=[];for(const x of rankedCandidates(pool.filter(q=>!blocked.has(q.id)),balanced)){let g=duplicateKey(x.q.id);if(blockedGroups.has(g))continue;out.push(x.q);blockedGroups.add(g);if(out.length>=n)break}return out}
function pickRealRegular(type,n,blocked){return coveragePick(Q.filter(q=>q.type===type),n,blocked)}
function recordExamRotation(items){let r=rotationState(),ids=[...new Set(items.map(x=>x.q.id))];r.round++;r.recent=[...(r.recent||[]),ids].slice(-10);for(const id of ids){r.usage[id]=(r.usage[id]||0)+1;r.lastSeenRound[id]=r.round;let l=S.learning[id]||(S.learning[id]={attempts:0,correct:0,wrong:0,streak:0,totalMs:0,timedAttempts:0,assistedCorrect:0,lowConfidenceCorrect:0,totalExposure:0,regularExposure:0,fillExposure:0,lastSeenRound:0,last:0,due:0});l.totalExposure++;let item=items.find(x=>x.q.id===id);if(item?.renderType==='fill')l.fillExposure++;else l.regularExposure++;l.lastSeenRound=r.round}saveStore()}
function typeName(t){return t==='single'?'单选题':t==='multiple'?'多选题':t==='judge'?'判断题':'填空题'}
function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function hashSeed(v){let h=2166136261;for(const c of String(v)){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0}
function stableOptionOrder(q,seed){let a=[...q.options],state=hashSeed(`${seed}:${q.id}`);for(let i=a.length-1;i>0;i--){state=(Math.imul(state,1664525)+1013904223)>>>0;let j=state%(i+1);[a[i],a[j]]=[a[j],a[i]]}return a}
function applyOptionOrders(items,seed){for(const item of items)item.optionOrder=S.settings.shuffleOptions&&item.renderType!=='fill'?stableOptionOrder(item.q,seed):[...item.q.options];return items}
function toast(msg){let e=document.createElement('div');e.className='toast';e.textContent=msg;document.body.append(e);setTimeout(()=>e.remove(),1800)}
function saveSeen(id){S.seen[id]=Date.now();queueSave()}
function normalizeAnswerSymbols(v=''){return String(v).normalize('NFKC').replace(/[•∙・]/g,'·').replace(/([nN])\s*[.·]\s*m/gi,'N·m').replace(/[−–—]/g,'-').replace(/(\d)\s*[~～]\s*(\d)/g,'$1-$2').replace(/(\d)\s*(?:至|到)\s*(\d)/g,'$1-$2').replace(/(\d)\s*[xX×*]\s*(\d)/g,'$1×$2')}
function cleanAns(a){return normalizeAnswerSymbols(a).replace(/^[A-F][\.．、]\s*/i,'').replace(/\s+/g,'').replace(/[“”"'‘’。.!！?？,，、;；:：()（）\[\]【】]/g,'').toLowerCase()}
function arrayEq(a,b){return a.length===b.length&&a.every(x=>b.includes(x))}
function fillTokens(s){return String(s||'').split(/[、,，;；\n\/]+/).map(cleanAns).filter(Boolean)}
function stripFillFraming(v){return v.replace(/^(正确答案是|正确答案为|答案是|答案为|应填写|应填入|应为|填写|填入)/,'')}
function containsEveryAnswerExactly(raw,answers){let rest=stripFillFraming(cleanAns(raw));for(const expected of [...answers].map(cleanAns).sort((a,b)=>b.length-a.length)){let at=rest.indexOf(expected);if(at<0)return false;rest=rest.slice(0,at)+rest.slice(at+expected.length)}return rest.length===0}
function answerCorrect(item,answer){try{const q=item?.q;if(!validatePaperItem(q,item?.renderType,item?.renderType==='fill'?item?.fillLevel:'standard'))return false;if(item.renderType==='fill'){if(typeof answer!=='string')return false;let entry=resolveFillEntry(q,item.fillLevel,item.fillVariantKey);if(!entry)return false;let raw=answer,accepted=entry.accepted||[];if(accepted.some(x=>cleanAns(x)===cleanAns(raw)))return true;let exp=questionAnswers(q,'fill',item.fillLevel,item.fillVariantKey);if(entry.ordered)return stripFillFraming(cleanAns(raw))===exp.map(cleanAns).join('');return containsEveryAnswerExactly(raw,exp)}if(item.renderType==='multiple'){if(!Array.isArray(answer)||answer.some(x=>typeof x!=='string'))return false;let got=[...new Set(answer.map(cleanAns))].sort(),exp=q.answers.map(cleanAns).sort();return arrayEq(got,exp)}if(typeof answer!=='string')return false;return cleanAns(answer)===cleanAns(q.answers[0]||'')}catch(e){return false}}
function formatDuration(ms=0){let sec=Math.max(0,Math.round(ms/1000)),h=Math.floor(sec/3600),m=Math.floor((sec%3600)/60),s=sec%60;return h?`${h}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`:`${m}:${String(s).padStart(2,'0')}`}
function formatQTime(ms=0){let sec=Math.max(0,Math.round(ms/1000));return sec<60?`${sec}秒`:`${Math.floor(sec/60)}分${String(sec%60).padStart(2,'0')}秒`}
function isActiveExam(){return !!(session&&session.kind==='exam'&&!session.finished)}
function isTimedSession(){return !!(session&&session.kind!=='fillStudy'&&!session.finished)}
function initExamTimer(){if(!isTimedSession())return;session.totalActiveMs=0;session.items.forEach(x=>x.timeMs=0);session._activeIndex=current;session._activeSince=document.hidden?null:performance.now();startTimerTicker()}
function flushExamTimer(){if(!isTimedSession()||session._activeSince==null)return;let now=performance.now(),d=Math.max(0,now-session._activeSince);session.totalActiveMs=(session.totalActiveMs||0)+d;let item=session.items[session._activeIndex];if(item&&!item.checked)item.timeMs=(item.timeMs||0)+d;session._activeSince=now}
function pauseExamTimer(){if(!isTimedSession())return;flushExamTimer();session._activeSince=null;if(isActiveExam())saveSession(false);else saveStore();updateTimerUI()}
function resumeExamTimer(){if(!isTimedSession()||document.hidden)return;session._activeIndex=current;session._activeSince=performance.now();updateTimerUI()}
function liveTotalMs(){if(!isTimedSession())return session?.totalActiveMs||0;let v=session.totalActiveMs||0;if(session._activeSince!=null)v+=Math.max(0,performance.now()-session._activeSince);return v}
function liveQuestionMs(){if(!session)return 0;let item=session.items[current],v=item?.timeMs||0;if(isTimedSession()&&session._activeSince!=null&&session._activeIndex===current&&!item?.checked)v+=Math.max(0,performance.now()-session._activeSince);return v}
function updateTimerUI(){let a=$('#examTimer'),b=$('#questionTimer'),c=$('#examTimerSide');if(a)a.textContent=formatDuration(liveTotalMs());if(b)b.textContent=formatQTime(liveQuestionMs());if(c)c.textContent=formatDuration(liveTotalMs())}
function startTimerTicker(){stopTimerTicker();timerTicker=setInterval(updateTimerUI,500);updateTimerUI()}
function stopTimerTicker(){if(timerTicker){clearInterval(timerTicker);timerTicker=null}}
function switchQuestion(i){if(!session||i<0||i>=session.items.length)return;if(isTimedSession())flushExamTimer();current=i;if(isTimedSession()){session._activeIndex=current;session._activeSince=document.hidden?null:performance.now();if(isActiveExam())saveSession(false);else queueSave()}renderQuestion('question')}
async function copyText(text){try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text);return true}}catch(e){}try{let t=document.createElement('textarea');t.value=text;t.style.position='fixed';t.style.opacity='0';document.body.appendChild(t);t.select();let ok=document.execCommand('copy');t.remove();return ok}catch(e){return false}}
