scoreLow:makeEggPool('scoreLow',[['胜败兵家事不期。','这套题对你实施了一次精准打击，先别急着开下一套。'],['知不足，然后能自反也。','问题已经暴露，接下来反而好办。'],['不积跬步，无以至千里。','从错得最多的一类开始收。'],['','本次表现有点散，先复盘再开新卷。']]),
