function renderEggAtlas(returnTo='settings'){let e=S.easterEggs||(S.easterEggs=emptyEggState()),got=new Set(e.discovered||[]),notes={score100:'满分表现',score90:'高分表现',score80:'接近高分',score70:'继续补强',score60:'低空过线',scoreLow:'低分复盘',score40:'重点补弱',score20:'重新起步',streak10:'连续答对',streak20:'长连对',wrong3:'连续答错',wrong5:'连错提醒',wrong10:'暂停乱答',repeat3:'同题反复错',repeat5:'顽固错题',corrected:'错题纠正',improved:'成绩进步',comeback:'后程逆转',rapidGuess:'过快低正确率',lateNight:'深夜学习提醒',title:'称号解锁'},cards=Object.entries(EGG_CATALOG).map(([id,x])=>`<div class="egg-entry ${got.has(id)?'':'locked'}"><b>${got.has(id)?x.icon+' '+esc(x.name):'？？？'}</b><small>${got.has(id)?esc(notes[id]||'学习事件'):'继续学习解锁'}</small></div>`).join('');app(`<div class="section-title"><div><h2>彩蛋图鉴</h2><p>已发现 ${got.size} / ${Object.keys(EGG_CATALOG).length} · 当前称号：${esc(e.currentTitle||'初窥门径')}</p></div><button class="btn" onclick="returnFromEggAtlas('${esc(returnTo)}')">返回</button></div><div class="egg-atlas">${cards}</div>`)}
