function updateWrongRecord(item,correct,assisted){let id=item.q.id,w=S.wrong[id]||{count:0,wrongTotal:0,wrongStreak:0,lastWrong:0,lastCorrect:0,independentCorrectStreak:0,assistedCorrect:0,recentResult:'',corrected:false},now=Date.now();if(!correct){w.count=Math.max(1,w.count||0);w.wrongTotal++;w.wrongStreak++;w.lastWrong=now;w.independentCorrectStreak=0;w.recentResult='wrong';w.corrected=false}else if(assisted){w.assistedCorrect++;w.lastCorrect=now;w.independentCorrectStreak=0;w.recentResult='assistedCorrect'}else{w.lastCorrect=now;w.wrongStreak=0;w.independentCorrectStreak++;w.recentResult='independentCorrect';if(w.count>0&&w.independentCorrectStreak>=2){w.count=0;w.corrected=true}}if(w.wrongTotal||w.count||w.corrected)S.wrong[id]=w}
