function renderConfidence(item){return `<div class="confidence-box"><span>本题信心：</span>${[['sure','确定会'],['hesitant','有点犹豫'],['guess','蒙的']].map(([v,t])=>`<button class="btn small ${item.confidence===v?'good':''}" onclick="setConfidence('${v}')">${t}</button>`).join('')}${item.assistedResult?'<small>本题为辅助后答对，不计独立答对</small>':''}</div>`}
