function sprintResultSummary(items){if(session.mode!=='sprint')return '';let frequent=items.filter(x=>(S.wrong[x.q.id]?.wrongTotal||0)>=2),slow=items.filter(x=>(x.timeMs||0)>=30000),risk=items.filter(x=>!x.correct||slow.includes(x)||['hesitant','guess'].includes(x.confidence)||(S.learning[x.q.id]?.due||0)<=Date.now()&&(S.learning[x.q.id]?.due||0)>0),improved=items.filter(x=>x.correct&&(S.wrong[x.q.id]?.independentCorrectStreak||0)>=1&&!slow.includes(x));let ids=a=>a.slice(0,8).map(x=>`#${x.q.id}`).join('、')||'无';return `<section class="panel pad sprint-summary"><h2>冲刺结论</h2><p><b>本轮冲刺后仍有 ${risk.length} 道高风险题，建议优先复习。</b></p><div class="dashboard-grid"><div><span>高频错题</span><strong>${ids(frequent)}</strong></div><div><span>高耗时题</span><strong>${ids(slow)}</strong></div><div><span>仍需重点复习</span><strong>${ids(risk)}</strong></div><div><span>已明显改善</span><strong>${ids(improved)}</strong></div></div></section>`}
function showExamEgg(score){let id=scoreEggId(score),prev=S.history?.[1],delta=prev&&Number.isFinite(prev.score)?score-prev.score:null,data=`本次 ${score} 分${delta==null?'':`，较上次${delta>=0?'+':''}${delta}分`}`,items=session?.items||[],half=Math.floor(items.length/2),first=items.slice(0,half),last=items.slice(half),rate=a=>a.length?a.filter(x=>x.correct).length/a.length:0,avg=items.length?items.reduce((n,x)=>n+num(x.timeMs,0),0)/items.length:0,correct=items.length?items.filter(x=>x.correct).length/items.length:0;if(items.length>=10&&avg>0&&avg<3000&&correct<.5){id='rapidGuess';data=`平均每题 ${formatQTime(avg)}，正确率 ${Math.round(correct*100)}%`}else if(first.length>=5&&rate(last)-rate(first)>=.3)id='comeback';else if(prev&&(delta>=10||(prev.score<90&&score>=90)))id='improved';let extras=consolidateEggCandidates(session?._eggCandidates||[]),title=session?._eggTitleCandidate||eligibleTitle();closeEasterEgg();showEasterEgg(id,data,true,extras,title)}
function renderResult(c,score){view='result';let wrong=session.items.filter(x=>!x.correct),total=session.totalActiveMs||session.items.reduce((a,x)=>a+(x.timeMs||0),0),avg=total/Math.max(1,session.items.length);let byType={},timeByType={};for(const x of session.items){let t=typeName(x.renderType);byType[t]=byType[t]||[0,0];byType[t][1]++;if(x.correct)byType[t][0]++;let z=timeByType[t]||(timeByType[t]={total:0,count:0});z.total+=x.timeMs||0;z.count++}let slow=[...session.items].sort((a,b)=>(b.timeMs||0)-(a.timeMs||0)),high=slow.filter(x=>(x.timeMs||0)>=30000&&(x.timeMs||0)>avg*1.5);session.highTimeItems=high;let timingRows=Object.entries(timeByType).map(([t,v])=>`<div class="stat"><b>${formatQTime(v.total/v.count)}</b><span>${t}平均</span></div>`).join('');app(`<div class="panel result-hero"><div class="score-ring" style="--pct:${score}%"><b>${score}分</b></div><div><h2 style="margin:0">${score>=90?'非常稳':score>=75?'整体不错':score>=60?'及格了，继续补弱项':'建议先刷错题再模拟'}</h2><p class="muted">答对 ${c}/${session.items.length} · 错题 ${wrong.length} 道已自动加入错题本</p><div class="result-grid">${Object.entries(byType).map(([t,v])=>`<div class="stat"><b>${v[0]}/${v[1]}</b><span>${t}</span></div>`).join('')}</div></div></div>${sprintResultSummary(session.items)}
<div class="section-title"><div><h2>⏱ 用时分析</h2><p>高耗时题：单题至少30秒，且超过本场平均用时的1.5倍</p></div></div><section class="dashboard-grid timing-summary"><div class="panel pad"><b>整场有效用时</b><div class="big-time">${formatDuration(total)}</div></div><div class="panel pad"><b>平均每题</b><div class="big-time">${formatQTime(avg)}</div></div><div class="panel pad"><b>高耗时题</b><div class="big-time">${high.length}道</div></div></section><div class="panel pad" style="margin-top:14px"><h3 style="margin-top:0">各题型平均用时</h3><div class="result-grid">${timingRows}</div></div>
<div class="section-title"><div><h2>高耗时 / 最慢题</h2><p>${high.length?`已自动标出 ${high.length} 道需要提高熟练度的题`:'本场没有达到“高耗时”阈值的题，下面仍列出最慢的题供参考'}</p></div><button class="btn primary" onclick="retrySlowCurrent()" ${high.length?'':'disabled'}>重练高耗时题</button></div><div class="review-list">${slow.slice(0,10).map((x,i)=>`<div class="panel review-item timing-item ${high.includes(x)?'slow-alert':''}"><h4>${i+1}. #${x.q.id} ${esc(fillStem(x.q,x.renderType,x.fillLevel,x.fillVariantKey))}</h4><p><b>${formatQTime(x.timeMs||0)}</b> · ${typeName(x.renderType)} · ${x.correct?'答对':'答错'} ${high.includes(x)?'· <span class="slow-badge">高耗时</span>':''}</p><button class="btn small" style="margin-top:8px" onclick="reviewOne(${x.q.id})">重做这题</button></div>`).join('')}</div>
<details class="panel pad timing-details"><summary>查看全部 ${session.items.length} 道题的逐题用时</summary><div class="timing-all-list">${session.items.map((x,i)=>`<button class="timing-row ${x.correct?'ok':'bad'}" onclick="reviewOne(${x.q.id})"><span>${i+1}. #${x.q.id} · ${typeName(x.renderType)}</span><b>${formatQTime(x.timeMs||0)}</b><em>${x.correct?'✓':'✗'}</em></button>`).join('')}</div></details>
<div class="section-title"><div><h2>本场复盘</h2><p>自动合并答错、未答、高耗时、辅助后答对与低信心正确题</p></div><div><button class="btn" onclick="navHome()">回首页</button> <button class="btn" onclick="redoCurrentPaper()">重做本卷</button> <button class="btn primary" onclick="reviewCurrentSession()">一键本场复盘</button></div></div><div class="review-list">${wrong.length?wrong.map(x=>`<div class="panel review-item"><h4>#${x.q.id} ${esc(fillStem(x.q,x.renderType,x.fillLevel,x.fillVariantKey))}</h4><p>本题用时：${formatQTime(x.timeMs||0)} · 正确答案：${esc(questionAnswers(x.q,x.renderType,x.fillLevel,x.fillVariantKey).join('；'))}</p><button class="btn small" style="margin-top:8px" onclick="reviewOne(${x.q.id})">重做这题</button></div>`).join(''):`<div class="panel empty">本场没有答错题；仍可复盘高耗时或低信心题。</div>`}</div>`);setTimeout(()=>showExamEgg(score),80)}
