function startPaperFromRecord(rec){let bad=rec?.paperDamaged||!rec?.ids?.length||!Array.isArray(rec.renderTypes)||!Array.isArray(rec.fillLevels)||rec.renderTypes.length!==rec.ids.length||rec.fillLevels.length!==rec.ids.length||new Set(rec.ids.map(Number)).size!==rec.ids.length||rec.fillVariantKeys!==undefined&&(!Array.isArray(rec.fillVariantKeys)||rec.fillVariantKeys.length!==rec.ids.length);if(!bad)for(let i=0;i<rec.ids.length;i++){let q=Q.find(x=>x.id===Number(rec.ids[i])),t=rec.renderTypes[i],l=t==='fill'?rec.fillLevels[i]:'standard';let key=rec.fillVariantKeys?.[i]??'';if(!VALID_IDS.has(Number(rec.ids[i]))||!validatePaperItem(q,t,l)||typeof key!=='string'||key!==''&&(t!=='fill'||!validFillVariantKey(q,l,key))){bad=true;break}}if(bad)return toast('该历史试卷数据损坏，无法重做');let byId=new Map(Q.map(q=>[q.id,q])),paperId=`${rec.paperId||makePaperId()}-R`,items=rec.ids.map((id,i)=>{let q=byId.get(Number(id)),raw=rec.optionOrders?.[i];return {q,renderType:rec.renderTypes[i],fillLevel:rec.renderTypes[i]==='fill'?rec.fillLevels[i]:'standard',fillVariantKey:rec.fillVariantKeys?.[i]||fallbackFillVariantKey(q,rec.renderTypes[i]==='fill'?rec.fillLevels[i]:'standard',rec.paperId||rec.ids.join('-')),answer:null,optionOrder:Array.isArray(raw)&&raw.length===q.options.length&&raw.every(o=>q.options.includes(o))&&new Set(raw).size===raw.length?[...raw]:(S.settings.shuffleOptions&&rec.renderTypes[i]!=='fill'?stableOptionOrder(q,rec.paperId||paperId):[...q.options]),checked:false,correct:null,showExplanation:false,assisted:false,revealed:false,attemptRecorded:false,confidence:'',timeMs:0}});session={kind:'exam',mode:'redo',title:`重做：${rec.mode||'历史试卷'}`,strict:false,fillLevel:'enhanced',started:Date.now(),finished:false,rotationRecorded:true,paperId,items};current=0;initExamTimer();saveSession();renderQuestion()}
