function renderSearch(){view='search';app(`<div class="section-title"><div><h2>题库搜索</h2><p>支持题号、题干、选项、答案、知识标签</p></div><button class="btn" onclick="navHome()">返回</button></div><div class="panel pad"><div class="toolbar"><input id="searchInput" style="flex:1;min-width:220px" placeholder="例如：扭力扳手 / MES / 170 / 不合格品" oninput="doSearch(this.value)"><select id="searchType" onchange="doSearch($('#searchInput').value)"><option value="all">全部题型</option><option value="single">单选</option><option value="multiple">多选</option><option value="judge">判断</option></select></div><div id="searchResults" class="search-results"><div class="empty">输入关键词开始搜索</div></div></div>`);setTimeout(()=>$('#searchInput')?.focus(),50)}
