function masteryStatus(q){let l=S.learning[q.id]||{},w=S.wrong[q.id]||{},avg=l.timedAttempts?l.totalMs/l.timedAttempts:0;if(S.reviewFlags[q.id])return '待复核';if((w.wrongStreak||0)>=2)return '反复错';if((w.count||0)>0)return '错题';if(l.due&&l.due<=Date.now())return 'SRS到期';if(avg>=30000)return '高耗时';if(S.favorites.includes(q.id))return '收藏';if((w.independentCorrectStreak||0)>=2||(S.mastery[q.id]==='mastered'&&(l.attempts||0)>0))return '熟练';if(S.mastery[q.id]==='fuzzy')return '不熟';return S.seen[q.id]?'不熟':'未见'}
function renderMasteryMap(){view='masteryMap';let rows=Q.map(q=>({q,status:masteryStatus(q)})),mastered=rows.filter(x=>x.status==='熟练'),seven=Date.now()-7*86400000,new7=mastered.filter(x=>(S.wrong[x.q.id]?.lastCorrect||S.learning[x.q.id]?.last||0)>=seven).length,due=rows.filter(x=>['SRS到期','错题','反复错','不熟'].includes(x.status)).length,everWrong=Object.values(S.wrong).filter(w=>(w.wrongTotal||0)>0),corrected=everWrong.filter(w=>w.corrected).length;app(`<div class="section-title"><div><h2>507题掌握度地图</h2><p>看过不等于掌握；熟练要求有效作答证据</p></div><button class="btn" onclick="navHome()">返回</button></div><section class="dashboard-grid"><div class="panel pad"><b>真正掌握率</b><div class="big-time">${Math.round(mastered.length/Q.length*100)}%</div></div><div class="panel pad"><b>近7天新增掌握</b><div class="big-time">${new7}</div></div><div class="panel pad"><b>待复习数量</b><div class="big-time">${due}</div></div><div class="panel pad"><b>错题纠正率</b><div class="big-time">${everWrong.length?Math.round(corrected/everWrong.length*100):0}%</div></div></section><div class="panel pad" style="margin-top:14px"><div class="mastery-map">${rows.map(x=>`<button class="mastery-cell" data-status="${x.status}" title="#${x.q.id} ${x.status}" onclick="reviewOne(${x.q.id})"><b>${x.q.id}</b><small>${x.status}</small></button>`).join('')}</div></div>`)}

